#!/usr/bin/env python3
"""Summarize completed full runs, preserving every per-run measurement in JSON."""
import json,sys,statistics
from pathlib import Path
root=Path(__file__).resolve().parent
chosen={}
for p in sorted((root/'results').glob('*.json')):
 r=json.loads(p.read_text())
 if r.get('measurement_schema')!=2:continue
 if r.get('method',{}).get('warmups')!=3 or r.get('method',{}).get('measured')!=10:continue
 for v in r['variants']:
  if v['status']=='complete' and len([x for x in v['runs'] if x['measured']])==10:chosen[v['variant']]=(p,r,v)
summary={'issue':'https://github.com/ledgerloops/ledgerloops/issues/44','variants':{},'strict_durable_ms':None}
report=['# Rocicorp Zero benchmark results','', 'Measurements implement [ledgerloops issue 44](https://github.com/ledgerloops/ledgerloops/issues/44) using the exact 415,448-byte synthetic fixture. All three requested models passed 3 warmups and 10 measured transfers each, with complete SHA-256 verification after offline browser reopening. Native relaxed IndexedDB persistence is reported separately from readability; strict durable completion remains unmeasured.','', '## Initial transfers','', 'Times are milliseconds. p95 uses nearest rank over 10 measured observations and equals the sample maximum. Persistence is the weaker native IDB transaction observation described in [README.md](README.md).','', '| Model | Readable p50 | p95 and max | IDB persistence p50 | p95 and max | Received application bytes p50 | Received transport bytes p50 |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for variant in ['typed','record','collection']:
 if variant not in chosen:
  report.append(f'| {variant} | unmeasured | | | | | |');continue
 p,r,v=chosen[variant];s=v['summary'];summary['variants'][variant]={'raw_result':p.name,'summary':s,'updates':v['updates'],'services':v['services'],'sender_preparation_ms':v['sender_preparation_ms']}
 a=s['readable_ms'];b=s['persistence_transaction_ms'];report.append(f"| {variant} | {a['p50']:.2f} | {a['p95_nearest_rank']:.2f} | {b['p50']:.2f} | {b['p95_nearest_rank']:.2f} | {s['received_application_bytes']['p50']:,.0f} | {s['received_transport_bytes']['p50']:,.0f} |")
report+=['','## Untimed preparation','', 'Median milliseconds across the 10 measured receivers. Zero open includes local store initialization and transport/authentication; these steps and browser startup occur before subscription timing. Sender preparation is one untimed preparation per model.','', '| Model | Browser startup p50 | Receiver script p50 | Zero open and connection p50 | Sender preparation |','| --- | ---: | ---: | ---: | ---: |']
for variant,(p,r,v) in chosen.items():
 conns=[x['connection'] for x in v['runs'] if x['measured']]
 report.append(f"| {variant} | {statistics.median(x['browser_startup_ms'] for x in conns):.2f} | {statistics.median(x['receiver_script_startup_ms'] for x in conns):.2f} | {statistics.median(x['connection_ms'] for x in conns):.2f} | {v['sender_preparation_ms']:.2f} |")
report+=['','## Receiver storage','', 'Exact bytes from measured receiver 1 for each model, after native close and browser shutdown. Values are apparent / allocated bytes; raw JSON contains baseline, total and net for every measured receiver. IndexedDB, WebStorage quota files, Local Storage identity and Session Storage metadata are counted; other browser profile files are excluded.','', '| Model | Initialized empty | After sync | Net growth |','| --- | ---: | ---: | ---: |']
fmt=lambda d:f"{d['apparent_bytes']:,} / {d['allocated_bytes']:,}"
for variant,(p,r,v) in chosen.items():
 row=next(x for x in v['runs'] if x['measured']);d=row['receiver_storage'];summary['variants'][variant]['receiver_example']=d;report.append(f"| {variant} | {fmt(d['baseline'])} | {fmt(d['total'])} | {fmt(d['net'])} |")
report+=['','## Incremental changes','', 'One subscribed receiver receives a deterministic 26-byte suffix to the issue title, then a 25-byte suffix to the note body. Convergence includes harness dispatch and the normal PostgreSQL transaction commit. Each update passes full equality verification, followed by offline reopening of the final changed fixture. These are individual observations, not ten-run percentiles.','', '| Model | Change | Readable ms | IDB persistence ms | Received application bytes | Received transport bytes |','| --- | --- | ---: | ---: | ---: | ---: |']
for variant,(p,r,v) in chosen.items():
 for u in v['updates']:report.append(f"| {variant} | {u['collection']}.{u['field']} | {u['readable_ms']:.2f} | {u['persistence_transaction_ms']:.2f} | {u['wire']['received']:,} | {u['transport_bytes']['received']:,} |")
report+=['','## Required service storage','', 'Exact apparent / allocated bytes. PostgreSQL totals include upstream, CVR and change databases, system catalogs, WAL and normal metadata. These final totals cover the entire model experiment, including all warmups, measured receivers and the incremental receiver. Empty PostgreSQL baselines include initialized databases. Cache preparation means its fully prepared replica before any clients; cache final totals include replica, WAL, WAL2 and shared-memory files after shutdown. No binaries or dependency directories are included.','', '| Model | Empty PostgreSQL cluster | Final PostgreSQL cluster | PostgreSQL net | Prepared cache files | Final cache files |','| --- | ---: | ---: | ---: | ---: | ---: |']
for variant,(p,r,v) in chosen.items():
 s=v['services'];sumfiles=lambda x:{k:sum(f[k] for f in x.values()) for k in ['apparent_bytes','allocated_bytes']};report.append(f"| {variant} | {fmt(s['initialized_empty_postgres'])} | {fmt(s['final_postgres'])} | {fmt(s['postgres_net'])} | {fmt(sumfiles(s['pre_client_cache_files']))} | {fmt(sumfiles(s['cache_files']))} |")
report+=['', '| Model | Upstream database bytes | CVR database bytes | Change database bytes |','| --- | ---: | ---: | ---: |']
for variant,(p,r,v) in chosen.items():
 d=v['services']['final_databases'];report.append(f"| {variant} | {d['upstream']:,} | {d['cvr']:,} | {d['change']:,} |")
report+=['','Database page sizes above use `pg_database_size`; allocated cluster totals are reported separately. Storage is not a per-client server estimate.','', '## Environment and interpretation','']
if chosen:
 r=next(iter(chosen.values()))[1];e=r['environment'];report+=[f"Measured on {r['started_utc'][:10]} UTC: {e['cpu_model']}, {e['logical_cpu_count']} logical CPUs, {e['ram_bytes']//(1024**3)} GiB RAM, macOS {e['os'].split('ProductVersion:')[1].split()[0]}, Darwin {e['kernel']}, {e['arch']}, APFS. Node {e['node']}, {e['postgres']}, Chromium {e.get('browser','see raw environment')}, Zero 1.11.3. Native processes; no container or cgroup CPU/RAM cap. Zero runs one sync worker. PostgreSQL fsync, full_page_writes and synchronous_commit remain enabled.",'', 'The shared atomic directory lock serializes sustained work across six tasks. Atomic Model H received priority before these full runs. Browser startup, connection/authentication, sender import and replica preparation are excluded from transfer timing and recorded separately where applicable. OS activity, file-provider behavior, disk fullness and thermal state remain uncontrolled. Storage paths and filesystem capacity at run start appear in each raw environment record. These are single-host observations with instrumentation overhead, not a cross-engine ranking.','', 'WebSocket payload and TCP stream counts are separate. HTTP upgrade headers are excluded from transfer snapshots. No WebSocket compression extension was negotiated in these runs, so the transport count is uncompressed application payload plus WebSocket framing. Captured handshakes are retained in raw results. Neither count includes IP/TCP headers or other service traffic.','', 'Typed columns preserve scalar queryability, complete-record JSON stores preserve one entity per row, and collection JSON stores preserve two coarse entities. Observed incremental byte counts show the practical cost of these boundaries. Source inspection of Zero 1.11.3 `client-handler.js` confirms that a `put` row patch sends row contents; changing a scalar column does not imply a scalar-only browser payload. No model uses a first-page limit.','', 'Strict power-loss durability has no measured value in this adapter. Relaxed IndexedDB transaction completion and successful normal-close reopening are weaker boundaries. See [README.md](README.md) for instrumentation, authorization, storage accounting, source references and reproducible commands.']
report+=['','## Artifacts','', '- [Runnable adapter and commands](README.md)','- [Exact fixture manifest](fixture/manifest.json)','- [Dependency lockfile](package-lock.json)','- [Machine readable summary](summary.json)']
for variant,(p,r,v) in chosen.items():report.append(f'- [{variant} raw measurements](results/{p.name})')
(root/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
(root/'REPORT.md').write_text('\n'.join(report)+'\n')
print('Summarized',','.join(chosen))
